def solve(date: str, months: int) -> str:
    def days_in_month(year: int, month: int) -> int:
        if month == 2:
            leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
            return 29 if leap else 28
        if month in (4, 6, 9, 11):
            return 30
        return 31

    if months == 0:
        return date

    year, month, day = map(int, date.split("-"))
    target_year, target_month_zero = divmod(year * 12 + month - 1 + months, 12)
    target_month = target_month_zero + 1
    target_last = days_in_month(target_year, target_month)

    if day == days_in_month(year, month):
        target_day = target_last
    else:
        target_day = min(day, target_last)

    return f"{target_year:04d}-{target_month:02d}-{target_day:02d}"

def solve(value: str, places: int) -> str:
    negative = value.startswith("-")
    unsigned = value.lstrip("+-")

    if "." in unsigned:
        whole, fraction = unsigned.split(".")
    else:
        whole, fraction = unsigned, ""

    digits = int(whole + fraction)
    discarded_places = len(fraction) - places

    if discarded_places > 0:
        divisor = 10 ** discarded_places
        retained, remainder = divmod(digits, divisor)
        halfway = divisor // 2
        if remainder > halfway or (remainder == halfway and retained % 2):
            retained += 1
    else:
        retained = digits * 10 ** (-discarded_places)

    if places < 0:
        result = str(retained * 10 ** (-places))
    elif places == 0:
        result = str(retained)
    else:
        padded = str(retained).zfill(places + 1)
        result = padded[:-places] + "." + padded[-places:]

    return "-" + result if negative and retained != 0 else result

def solve(versions: list[str]) -> list[str]:
    def precedence(version: str):
        main = version.split("+", 1)[0]
        core, separator, prerelease = main.partition("-")
        major, minor, patch = (int(part) for part in core.split("."))

        if not separator:
            return major, minor, patch, 1, ()

        identifiers = tuple(
            (0, int(part)) if part.isascii() and part.isdigit() else (1, part)
            for part in prerelease.split(".")
        )
        return major, minor, patch, 0, identifiers

    return sorted(versions, key=precedence)

def solve(numerator: int, denominator: int) -> str:
    if numerator == 0:
        return "0"

    sign = "-" if numerator < 0 else ""
    integer, remainder = divmod(abs(numerator), denominator)

    if remainder == 0:
        return sign + str(integer)

    digits = []
    seen = {}

    while remainder and remainder not in seen:
        seen[remainder] = len(digits)
        digit, remainder = divmod(remainder * 10, denominator)
        digits.append(str(digit))

    if remainder == 0:
        return sign + str(integer) + "." + "".join(digits)

    cycle_start = seen[remainder]
    return (
        sign
        + str(integer)
        + "."
        + "".join(digits[:cycle_start])
        + "("
        + "".join(digits[cycle_start:])
        + ")"
    )

def solve(numeral: str) -> int | None:
    import re

    if not numeral or re.fullmatch(
        r"M{0,3}(?:CM|CD|D?C{0,3})(?:XC|XL|L?X{0,3})(?:IX|IV|V?I{0,3})",
        numeral,
    ) is None:
        return None

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0

    for index, symbol in enumerate(numeral):
        value = values[symbol]
        if index + 1 < len(numeral) and value < values[numeral[index + 1]]:
            total -= value
        else:
            total += value

    return total

from collections import OrderedDict


def solve(capacity: int, operations: list[list]) -> list[list]:
    cache = OrderedDict()
    get_results = []

    for operation in operations:
        action, key = operation[:2]

        if action == "put":
            cache[key] = operation[2]
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif action == "get":
            if key in cache:
                get_results.append(cache[key])
                cache.move_to_end(key)
            else:
                get_results.append(None)
        elif action == "delete":
            cache.pop(key, None)

    return [get_results, list(reversed(cache))]

def solve(words: list[str]) -> list[list[str]]:
    import unicodedata

    groups: dict[str, list[str]] = {}

    for word in words:
        decomposed = unicodedata.normalize("NFKD", word)
        without_marks = "".join(
            char for char in decomposed
            if unicodedata.category(char) != "Mn"
        )
        key = " ".join(without_marks.casefold().split())
        groups.setdefault(key, []).append(word)

    return list(groups.values())

def solve(document, pointers: list[str]) -> list[list]:
    results = []

    for pointer in pointers:
        if pointer == "":
            results.append([True, document])
            continue

        value = document
        found = True

        for raw_token in pointer[1:].split("/"):
            token = raw_token.replace("~1", "/").replace("~0", "~")

            if isinstance(value, dict):
                if token not in value:
                    found = False
                    break
                value = value[token]
            elif isinstance(value, list):
                if not token or (len(token) > 1 and token[0] == "0"):
                    found = False
                    break
                if any(char < "0" or char > "9" for char in token):
                    found = False
                    break
                try:
                    index = int(token)
                except ValueError:
                    found = False
                    break
                if index >= len(value):
                    found = False
                    break
                value = value[index]
            else:
                found = False
                break

        results.append([True, value] if found else [False, None])

    return results

