from datetime import date as Date


def solve(date: str, days: int, holidays: list[str]) -> str:
    start = Date.fromisoformat(date).toordinal()
    if days == 0:
        return date

    holiday_ordinals = sorted({
        ordinal
        for holiday in holidays
        if (ordinal := Date.fromisoformat(holiday).toordinal()) % 7 <= 5
    })

    def business_days_through(ordinal: int) -> int:
        weeks, remaining = divmod(ordinal, 7)
        weekdays = weeks * 5 + min(remaining, 5)
        return weekdays - bisect_right(holiday_ordinals, ordinal)

    if days > 0:
        target = business_days_through(start) + days
        low, high = start + 1, Date.max.toordinal()
    else:
        target = business_days_through(start - 1) + days + 1
        low, high = 1, start - 1

    while low < high:
        middle = (low + high) // 2
        if business_days_through(middle) >= target:
            high = middle
        else:
            low = middle + 1

    return Date.fromordinal(low).isoformat()

def solve(edges: list[list], start: str, end: str) -> list | None:
    import heapq

    if start == end:
        return [0, [start]]

    outgoing = {}
    incoming = {}

    for source, destination, weight in edges:
        outgoing.setdefault(source, []).append((destination, weight))
        incoming.setdefault(destination, []).append((source, weight))

    best = {end: (0, 0)}
    heap = [(0, 0, end)]

    while heap:
        total, hops, node = heapq.heappop(heap)
        if (total, hops) != best[node]:
            continue

        for previous, weight in incoming.get(node, ()):
            candidate = (total + weight, hops + 1)
            if previous not in best or candidate < best[previous]:
                best[previous] = candidate
                heapq.heappush(heap, (*candidate, previous))

    if start not in best:
        return None

    path = [start]
    node = start

    while node != end:
        remaining_weight, remaining_hops = best[node]
        node = min(
            destination
            for destination, weight in outgoing[node]
            if destination in best
            and weight + best[destination][0] == remaining_weight
            and best[destination][1] + 1 == remaining_hops
        )
        path.append(node)

    return [best[start][0], path]

def solve(length: int, fragments: list[list]) -> str | None:
    if length < 0:
        return None

    characters = [None] * length

    for offset, text in fragments:
        if offset < 0 or offset + len(text) > length:
            return None

        for index, character in enumerate(text):
            position = offset + index
            existing = characters[position]
            if existing is not None and existing != character:
                return None
            characters[position] = character

    if any(character is None for character in characters):
        return None

    return "".join(characters)

def solve(dimensions: list[int]) -> list:
    n = len(dimensions) - 1
    if n == 0:
        return [0, ""]

    costs = [[0] * n for _ in range(n)]
    renderings = [[""] * n for _ in range(n)]

    for i in range(n):
        renderings[i][i] = f"A{i + 1}"

    for length in range(2, n + 1):
        for left in range(n - length + 1):
            right = left + length - 1
            best_cost = None
            best_rendering = ""

            for split in range(left, right):
                cost = (
                    costs[left][split]
                    + costs[split + 1][right]
                    + dimensions[left]
                    * dimensions[split + 1]
                    * dimensions[right + 1]
                )
                if best_cost is None or cost <= best_cost:
                    rendering = (
                        f"({renderings[left][split]}"
                        f"{renderings[split + 1][right]})"
                    )
                    if (
                        best_cost is None
                        or cost < best_cost
                        or rendering < best_rendering
                    ):
                        best_cost = cost
                        best_rendering = rendering

            costs[left][right] = best_cost
            renderings[left][right] = best_rendering

    return [costs[0][n - 1], renderings[0][n - 1]]

def solve(value: int) -> str:
    if value == 0:
        return "0"

    digits = []
    while value:
        value, remainder = divmod(value, 3)
        if remainder == 2:
            digits.append("T")
            value += 1
        else:
            digits.append(str(remainder))

    return "".join(reversed(digits))

def solve(nodes: list[str], edges: list[list[str]]) -> list[list[str]] | None:
    adjacency = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for source, destination in edges:
        adjacency[source].append(destination)
        indegree[destination] += 1

    layer = sorted(node for node in nodes if indegree[node] == 0)
    layers = []
    processed = 0

    while layer:
        layers.append(layer)
        processed += len(layer)
        next_layer = []

        for source in layer:
            for destination in adjacency[source]:
                indegree[destination] -= 1
                if indegree[destination] == 0:
                    next_layer.append(destination)

        layer = sorted(next_layer)

    return layers if processed == len(nodes) else None

def solve(grid: list[list[int | None]]) -> list | None:
    if not grid or not grid[0] or grid[0][0] is None or grid[-1][-1] is None:
        return None

    rows, cols = len(grid), len(grid[0])
    costs = [[None] * cols for _ in range(rows)]
    counts = [[0] * cols for _ in range(rows)]

    for row in range(rows - 1, -1, -1):
        for col in range(cols - 1, -1, -1):
            value = grid[row][col]
            if value is None:
                continue

            if row == rows - 1 and col == cols - 1:
                costs[row][col] = value
                counts[row][col] = 1
                continue

            for next_row, next_col in ((row + 1, col), (row, col + 1)):
                if next_row >= rows or next_col >= cols:
                    continue
                next_cost = costs[next_row][next_col]
                if next_cost is None:
                    continue
                candidate = value + next_cost
                if costs[row][col] is None or candidate < costs[row][col]:
                    costs[row][col] = candidate
                    counts[row][col] = counts[next_row][next_col]
                elif candidate == costs[row][col]:
                    counts[row][col] += counts[next_row][next_col]

    if costs[0][0] is None:
        return None

    moves = []
    row = col = 0
    while row != rows - 1 or col != cols - 1:
        if row + 1 < rows and costs[row + 1][col] is not None:
            if grid[row][col] + costs[row + 1][col] == costs[row][col]:
                moves.append("D")
                row += 1
                continue
        moves.append("R")
        col += 1

    return [costs[0][0], counts[0][0], "".join(moves)]

def solve(pattern: str, text: str) -> bool:
    tokens = []
    index = 0

    while index < len(pattern):
        char = pattern[index]
        if char == "\\":
            index += 1
            tokens.append(("literal", pattern[index]))
        elif char == "?":
            tokens.append(("any", None))
        elif char == "*":
            if not tokens or tokens[-1][0] != "star":
                tokens.append(("star", None))
        else:
            tokens.append(("literal", char))
        index += 1

    matches = [False] * (len(text) + 1)
    matches[0] = True

    for kind, value in tokens:
        if kind == "star":
            for position in range(1, len(matches)):
                matches[position] = matches[position] or matches[position - 1]
        else:
            for position in range(len(text), 0, -1):
                matches[position] = matches[position - 1] and (
                    kind == "any" or text[position - 1] == value
                )
            matches[0] = False

        if not any(matches):
            return False

    return matches[-1]

def solve(formula: str) -> list[list]:
    def read_multiplier(index: int) -> tuple[int, int]:
        start = index
        while index < length and "0" <= formula[index] <= "9":
            index += 1
        return (int(formula[start:index]), index) if index > start else (1, index)

    length = len(formula)
    stack = [{}]
    index = 0

    while index < length:
        char = formula[index]

        if char == "(":
            stack.append({})
            index += 1
        elif char == ")":
            group = stack.pop()
            multiplier, index = read_multiplier(index + 1)
            parent = stack[-1]
            for symbol, count in group.items():
                parent[symbol] = parent.get(symbol, 0) + count * multiplier
        else:
            start = index
            index += 1
            while index < length and "a" <= formula[index] <= "z":
                index += 1
            symbol = formula[start:index]
            multiplier, index = read_multiplier(index)
            counts = stack[-1]
            counts[symbol] = counts.get(symbol, 0) + multiplier

    return [[symbol, count] for symbol, count in sorted(stack[0].items())]

