def solve(numerator: int, denominator: int, max_denominator: int) -> list[int]:
    best_a = 0
    best_b = 1
    best_error = None

    for b in range(1, max_denominator + 1):
        scaled = numerator * b
        lower = scaled // denominator

        for a in (lower, lower + 1):
            error = abs(a * denominator - scaled)

            if best_error is None:
                better = True
            else:
                current = error * best_b
                previous = best_error * b
                better = (
                    current < previous
                    or (
                        current == previous
                        and (b < best_b or (b == best_b and a < best_a))
                    )
                )

            if better:
                best_a = a
                best_b = b
                best_error = error

    return [best_a, best_b]

