def solve(operations: list[list]) -> list[list[int]]:
    stack = None
    pop_results = None
    saves = []

    for operation in operations:
        name = operation[0]

        if name == "push":
            stack = (operation[1], stack)
        elif name == "pop":
            value, stack = stack
            pop_results = (value, pop_results)
        elif name == "dup":
            stack = (stack[0], stack)
        elif name == "swap":
            top, rest = stack
            second, rest = rest
            stack = (second, (top, rest))
        elif name == "add" or name == "sub":
            top, rest = stack
            second, rest = rest
            value = second + top if name == "add" else second - top
            stack = (value, rest)
        elif name == "begin":
            saves.append((stack, pop_results))
        elif name == "commit":
            saves.pop()
        elif name == "rollback":
            stack, pop_results = saves.pop()

    final_stack = []
    while stack is not None:
        value, stack = stack
        final_stack.append(value)
    final_stack.reverse()

    results = []
    while pop_results is not None:
        value, pop_results = pop_results
        results.append(value)
    results.reverse()

    return [final_stack, results]

def solve(total: int, weights: list[int]) -> list[int]:
    if total == 0:
        return [0] * len(weights)

    magnitude = abs(total)
    weight_sum = sum(weights)
    shares = []
    remainders = []

    for weight in weights:
        share, remainder = divmod(magnitude * weight, weight_sum)
        shares.append(share)
        remainders.append(remainder)

    remaining = magnitude - sum(shares)
    for index in sorted(range(len(weights)), key=lambda i: (-remainders[i], i))[:remaining]:
        shares[index] += 1

    return [-share for share in shares] if total < 0 else shares

def solve(items: list[str]) -> list[str]:
    import re

    def sort_key(item: str):
        runs = []
        digit_lengths = []

        for run in re.findall(r"[0-9]+|[^0-9]+", item):
            if "0" <= run[0] <= "9":
                significant = run.lstrip("0")
                runs.append((0, len(significant), significant))
                digit_lengths.append(len(run))
            else:
                runs.append((1, run.lower()))

        return runs, digit_lengths, item

    return sorted(items, key=sort_key)

def solve(buildings: list[tuple[int, int, int]]) -> list[tuple[int, int]]:
    import heapq

    events = []
    for left, right, height in buildings:
        if height > 0:
            events.append((left, -height, right))
            events.append((right, 0, 0))

    events.sort()
    active = []
    result = []
    index = 0

    while index < len(events):
        x = events[index][0]

        while index < len(events) and events[index][0] == x:
            _, negative_height, right = events[index]
            if negative_height:
                heapq.heappush(active, (negative_height, right))
            index += 1

        while active and active[0][1] <= x:
            heapq.heappop(active)

        height = -active[0][0] if active else 0
        if not result or result[-1][1] != height:
            result.append((x, height))

    return result

def solve(lo: int, hi: int, digit: int) -> int:
    def count_through(n: int) -> int:
        if n < 0:
            return 0

        total = 1 if digit == 0 else 0
        place = 1

        while place <= n:
            higher = n // (place * 10)
            current = (n // place) % 10
            lower = n % place

            if digit == 0:
                if higher:
                    total += (higher - 1) * place
                    total += lower + 1 if current == 0 else place
            else:
                total += higher * place
                if current > digit:
                    total += place
                elif current == digit:
                    total += lower + 1

            place *= 10

        return total

    return count_through(hi) - count_through(lo - 1)

def solve(text: str) -> int | None:
    if not text:
        return None

    base = 10
    start = 0

    if len(text) >= 2 and text[0] == "0":
        prefix = text[1]
        if prefix in "bB":
            base = 2
        elif prefix in "oO":
            base = 8
        elif prefix in "xX":
            base = 16

        if base != 10:
            start = 2
            if start < len(text) and text[start] == "_":
                start += 1

    if start == len(text):
        return None

    value = 0
    previous_was_digit = False
    has_nonzero_decimal_digit = False

    for char in text[start:]:
        if char == "_":
            if not previous_was_digit:
                return None
            previous_was_digit = False
            continue

        if "0" <= char <= "9":
            digit = ord(char) - ord("0")
        elif base == 16 and "a" <= char <= "f":
            digit = ord(char) - ord("a") + 10
        elif base == 16 and "A" <= char <= "F":
            digit = ord(char) - ord("A") + 10
        else:
            return None

        if digit >= base:
            return None

        value = value * base + digit
        previous_was_digit = True
        if base == 10 and digit != 0:
            has_nonzero_decimal_digit = True

    if not previous_was_digit:
        return None
    if base == 10 and text[0] == "0" and has_nonzero_decimal_digit:
        return None

    return value

def solve(records: list[dict], spec: str) -> list[int]:
    from functools import cmp_to_key

    fields = [(part.lstrip("-"), part.startswith("-")) for part in spec.split(",")]

    def compare(left_index: int, right_index: int) -> int:
        left_record = records[left_index]
        right_record = records[right_index]

        for field, descending in fields:
            left = left_record.get(field)
            right = right_record.get(field)

            if left is None or right is None:
                if left is None and right is None:
                    continue
                return 1 if left is None else -1

            left_key = (0, left) if isinstance(left, int) else (1, left.lower(), left)
            right_key = (0, right) if isinstance(right, int) else (1, right.lower(), right)

            if left_key != right_key:
                result = -1 if left_key < right_key else 1
                return -result if descending else result

        return 0

    return sorted(range(len(records)), key=cmp_to_key(compare))

def solve(text: str, need: str) -> str:
    if not need:
        return ""

    required = {}
    for char in need:
        required[char] = required.get(char, 0) + 1

    missing = len(need)
    left = 0
    best_start = 0
    best_length = len(text) + 1

    for right, char in enumerate(text):
        if char in required:
            if required[char] > 0:
                missing -= 1
            required[char] -= 1

        while missing == 0:
            length = right - left + 1
            if length < best_length:
                best_start = left
                best_length = length

            outgoing = text[left]
            if outgoing in required:
                required[outgoing] += 1
                if required[outgoing] > 0:
                    missing += 1
            left += 1

    if best_length > len(text):
        return ""
    return text[best_start:best_start + best_length]

def solve(text: str) -> dict[str, dict[str, str]] | None:
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        line = line.strip(" \t")

        if not line or line[0] in ";#":
            continue

        if line.startswith("[") and line.endswith("]"):
            name = line[1:-1].strip(" \t").lower()
            if not name:
                return None
            current_section = name
            sections.setdefault(name, {})
            continue

        if "=" in line:
            key, value = line.split("=", 1)
            key = key.strip(" \t").lower()
            if not key:
                return None
            value = value.strip(" \t")
            if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            sections.setdefault(current_section if current_section is not None else "", {})[key] = value
            continue

        return None

    return sections

def solve(a: list[list[int]], b: list[int]) -> list[tuple[int, int]] | str:
    from fractions import Fraction

    m = len(a)
    n = len(a[0])
    rows = [[Fraction(value) for value in row] + [Fraction(b[i])]
            for i, row in enumerate(a)]

    pivot_columns = []
    rank = 0

    for col in range(n):
        pivot = next((r for r in range(rank, m) if rows[r][col]), None)
        if pivot is None:
            continue

        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        pivot_row = rows[rank]

        for r in range(rank + 1, m):
            if rows[r][col]:
                factor = rows[r][col] / pivot_row[col]
                rows[r][col] = Fraction(0)
                for c in range(col + 1, n + 1):
                    rows[r][c] -= factor * pivot_row[c]

        pivot_columns.append(col)
        rank += 1
        if rank == m:
            break

    if any(rows[r][n] for r in range(rank, m)):
        return "none"
    if rank < n:
        return "many"

    solution = [Fraction(0) for _ in range(n)]
    for r in range(rank - 1, -1, -1):
        col = pivot_columns[r]
        remainder = rows[r][n] - sum(
            rows[r][c] * solution[c] for c in range(col + 1, n)
        )
        solution[col] = remainder / rows[r][col]

    return [(value.numerator, value.denominator) for value in solution]

def solve(heights: list[list[int]]) -> int:
    import heapq

    if not heights or not heights[0]:
        return 0

    rows = len(heights)
    cols = len(heights[0])
    if rows < 3 or cols < 3:
        return 0

    visited = bytearray(rows * cols)
    heap = []

    def add_border(row: int, col: int) -> None:
        index = row * cols + col
        if not visited[index]:
            visited[index] = 1
            heapq.heappush(heap, (heights[row][col], row, col))

    for col in range(cols):
        add_border(0, col)
        add_border(rows - 1, col)

    for row in range(1, rows - 1):
        add_border(row, 0)
        add_border(row, cols - 1)

    trapped = 0
    while heap:
        level, row, col = heapq.heappop(heap)

        for next_row, next_col in (
            (row - 1, col),
            (row + 1, col),
            (row, col - 1),
            (row, col + 1),
        ):
            if not (0 <= next_row < rows and 0 <= next_col < cols):
                continue

            index = next_row * cols + next_col
            if visited[index]:
                continue

            visited[index] = 1
            height = heights[next_row][next_col]
            if height < level:
                trapped += level - height
            heapq.heappush(
                heap, (max(level, height), next_row, next_col)
            )

    return trapped

def solve(query: str) -> dict[str, list[str]]:
    def decode(text: str) -> str:
        data = bytearray()
        i = 0
        hex_digits = "0123456789abcdefABCDEF"

        while i < len(text):
            char = text[i]
            if char == "+":
                data.append(32)
            elif (
                char == "%"
                and i + 2 < len(text)
                and text[i + 1] in hex_digits
                and text[i + 2] in hex_digits
            ):
                data.append(int(text[i + 1:i + 3], 16))
                i += 2
            else:
                data.extend(char.encode("utf-8"))
            i += 1

        return data.decode("utf-8", "replace")

    if query.startswith("?"):
        query = query[1:]

    result: dict[str, list[str]] = {}
    for piece in query.split("&"):
        if not piece:
            continue
        name, separator, value = piece.partition("=")
        result.setdefault(decode(name), []).append(decode(value if separator else ""))

    return result

def solve(program: list[str]) -> list[int] | None:
    def wrap(value: int) -> int:
        return (value + 2**31) % 2**32 - 2**31

    stack: list[int] = []

    for instruction in program:
        if not isinstance(instruction, str):
            return None

        if instruction.startswith("push "):
            operand = instruction[5:]
            digits = operand[1:] if operand.startswith("-") else operand
            if not digits or any(char < "0" or char > "9" for char in digits):
                return None

            value = 0
            for char in digits:
                value = (value * 10 + ord(char) - ord("0")) % 2**32
            stack.append(wrap(-value if operand.startswith("-") else value))
            continue

        if instruction == "pop":
            if not stack:
                return None
            stack.pop()
        elif instruction == "dup":
            if not stack:
                return None
            stack.append(stack[-1])
        elif instruction == "swap":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == "neg":
            if not stack:
                return None
            stack[-1] = wrap(-stack[-1])
        elif instruction in ("add", "sub", "mul", "div", "mod"):
            if len(stack) < 2:
                return None
            b = stack[-1]
            a = stack[-2]
            if instruction in ("div", "mod") and b == 0:
                return None

            if instruction == "add":
                result = a + b
            elif instruction == "sub":
                result = a - b
            elif instruction == "mul":
                result = a * b
            else:
                quotient = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    quotient = -quotient
                result = quotient if instruction == "div" else a - b * quotient

            stack[-2:] = [wrap(result)]
        else:
            return None

    return stack
